int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N;
    cin >> N;

    // It is possible iff N is odd.
    // Construction:
    // For N = 1: edge 1-2.
    // For odd N >= 3:
    // Use vertices 1..N and N+1..2N.
    // Build:
    // 1 - 2
    // 1 - (N+1)
    // (N+1) - (N+3)
    // For each odd i = 3,5,...,N-2:
    //   1 - i
    //   i - i+1
    //   i - (N+i)
    //   (N+i) - (N+i+1)
    // Finally:
    //   N - 2
    //   N - (N+2)
    //
    // This gives a tree with 2N vertices and satisfies the XOR condition.

    if (N % 2 == 0) {
        cout << "No\n";
        return 0;
    }

    cout << "Yes\n";

    vector<pair<int,int>> edges;

    if (N == 1) {
        edges.push_back({1, 2});
    } else {
        int n = (int)N;

        edges.push_back({1, 2});
        edges.push_back({1, n + 1});
        edges.push_back({n + 1, n + 3});

        for (int i = 3; i <= n - 2; i += 2) {
            edges.push_back({1, i});
            edges.push_back({i, i + 1});
            edges.push_back({i, n + i});
            edges.push_back({n + i, n + i + 1});
        }

        edges.push_back({n, 2});
        edges.push_back({n, n + 2});
    }

    for (auto &e : edges) {
        cout << e.first << ' ' << e.second << '\n';
    }

    return 0;
}

