int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    /* It is possible iff N is odd.
       Construction for odd N:
       Let a_i = i, b_i = N+i.
       Add edge (a_i, b_i) for all i.
       For i = 1..N-1, add edge (b_i, a_{i+1}).

       Then the graph is a path:
       a1 - b1 - a2 - b2 - ... - aN - bN

       For each i:
       - If i is odd, path from a_i to b_i is just [a_i, b_i], xor = i^i = 0? No.
       So this simple path does NOT work.

       We use the standard odd-N construction:
       Build edges:
         for odd i < N:   (i, i+1), (N+i, N+i+1)
         for odd i < N:   (i, N+i+1), (N+i, i+1)
       and connect the last pair through 1:
         (N, 1), (2N, N+1)
       This forms a tree for odd N and satisfies the condition.
    */

    if (N % 2 == 0) {
        puts("No");
        return 0;
    }

    puts("Yes");

    /* Number of edges is 2N-1 */
    Edge *edges = (Edge*)malloc(sizeof(Edge) * (2 * N));
    int m = 0;

    if (N == 1) {
        edges[m++] = (Edge){1, 2};
    } else {
        for (int i = 1; i <= N - 2; i += 2) {
            edges[m++] = (Edge){i, i + 1};
            edges[m++] = (Edge){N + i, N + i + 1};
            edges[m++] = (Edge){i, N + i + 1};
            edges[m++] = (Edge){N + i, i + 1};
        }
        edges[m++] = (Edge){N - 1, N};
        edges[m++] = (Edge){2 * N - 1, 2 * N};
        edges[m++] = (Edge){N, 1};
        edges[m++] = (Edge){2 * N, N + 1};
    }

    for (int i = 0; i < m; i++) {
        printf("%d %d\n", edges[i].u, edges[i].v);
    }

    free(edges);
    return 0;
}

